    goals: [
      { id: "scn-v32-04-goal-1", desc: "人口达到 450 人", check: function (state) { return ((state && state.pop) ? state.pop.count : 0) >= 450; } },
      { id: "scn-v32-04-goal-2", desc: "幸福度保持 ≥70", check: function (state) { return ((state && state.pop) ? state.pop.happiness : 0) >= 70; } },
      { id: "scn-v32-04-goal-3", desc: "建成 2 座「铸币厂」", check: function (state) { return ((state && state.buildings) ? state.buildings.count("铸币厂") : 0) >= 2; } },
    ],
    checkWin(state) {
      const pop = (state && state.pop) ? state.pop.count : 0;
      const hap = (state && state.pop) ? state.pop.happiness : 0;
      const bld = (state && state.buildings) ? state.buildings.count("铸币厂") : 0;
      return pop >= 450 && hap >= 70 && bld >= 2;
    },
    checkLose(state) {
      const pop = (state && state.pop) ? state.pop.count : 0;
      const hap = (state && state.pop) ? state.pop.happiness : 0;
      const day = (state && state.day) ? state.day : 0;
      if (pop <= 0) return true;
      if (hap < 40) return true;
      if (day > 200) return true;
      return false;
    },
    timeLimitDays: 200,
    reward: { credits: 2000, tech: 60, title: "货币危机征服者" },
