  // 时间线总览：限时 200 天，10 个事件按 2%/7%/13%/23%/33%/47%/60%/77%/93%/98% 节点触发，终局在第 200 天。
  // 关键决策点：第 94 天转折点（47% 节点）决定胜负，之前必须建成 2 座「深空天线」并备足钢。
  // 失败模式：人口归零、幸福度连续 15 天低于 55、限时耗尽未达目标，三者任一即失败。
