  // 奖励估值：3000 星币 + 100 科技点 + 称号「AI伦理征服者」，合计约 3800 铁当量（星币 1:1、科技点 1:8 折算）。
  // 时间线总览：限时 240 天，10 个事件按 2%/7%/13%/23%/33%/47%/60%/77%/93%/98% 节点触发，终局在第 240 天。
  // 关键决策点：第 113 天转折点（47% 节点）决定胜负，之前必须建成 3 座「AI伦理委员会」并备足星币。
  // 失败模式：人口归零、幸福度连续 15 天低于 55、限时耗尽未达目标，三者任一即失败。
