    setup(game) {
      try {
        if (!game || !game.player || !game.player.inv) return;
        game.player.inv.iron = 200;
        game.player.inv.steel = 100;
        game.player.inv.food = 100;
        game.player.inv.credits = 4000;
      } catch (e) { /* setup 失败不阻断剧本加载 */ }
    },
    goals: [
      { id: "scn-v32-19-goal-1", desc: "人口达到 500 人", check: function (state) { return ((state && state.pop) ? state.pop.count : 0) >= 500; } },
      { id: "scn-v32-19-goal-2", desc: "幸福度保持 ≥70", check: function (state) { return ((state && state.pop) ? state.pop.happiness : 0) >= 70; } },
      { id: "scn-v32-19-goal-3", desc: "建成 3 座「生态穹顶」", check: function (state) { return ((state && state.buildings) ? state.buildings.count("生态穹顶") : 0) >= 3; } },
    ],
    checkWin(state) {
      const pop = (state && state.pop) ? state.pop.count : 0;
      const hap = (state && state.pop) ? state.pop.happiness : 0;
      const bld = (state && state.buildings) ? state.buildings.count("生态穹顶") : 0;
      return pop >= 500 && hap >= 70 && bld >= 3;
    },
    checkLose(state) {
      const pop = (state && state.pop) ? state.pop.count : 0;
      const hap = (state && state.pop) ? state.pop.happiness : 0;
      const day = (state && state.day) ? state.day : 0;
      if (pop <= 0) return true;
      if (hap < 40) return true;
      if (day > 220) return true;
      return false;
    },
